<?php
require_once __DIR__ . '/../includes/bootstrap.php'; require_student(); $pageTitle='My portal'; $user=current_user();
try { $conn=db(); $stmt=$conn->prepare('SELECT s.* FROM students s WHERE s.user_id=? LIMIT 1'); $stmt->bind_param('i',$user['id']); $stmt->execute(); $student=$stmt->get_result()->fetch_assoc();
  $reg=$conn->prepare('SELECT e.title,e.event_date,e.category,r.registered_at FROM registrations r JOIN events e ON e.id=r.event_id JOIN students s ON s.id=r.student_id WHERE s.user_id=? ORDER BY r.registered_at DESC'); $reg->bind_param('i',$user['id']); $reg->execute(); $registrations=$reg->get_result()->fetch_all(MYSQLI_ASSOC);
} catch(Throwable $ex) { $student=null; $registrations=[]; $dbError=true; error_log('Student dashboard: '.$ex->getMessage()); }
require __DIR__ . '/../includes/header.php'; ?>
<section class="page-hero"><div class="container dashboard-heading"><div><p class="eyebrow">Student portal</p><h1>Welcome, <?=e($user['name'])?>.</h1><p class="lead">Your student details and event activity in one place.</p></div><a class="button-secondary" href="<?=e(app_url('event.php'))?>">Explore events</a></div></section><section class="section"><div class="container"><div class="dashboard-grid"><div class="stat-card"><span>Account role</span><strong style="font-size:1.4rem">Student</strong></div><div class="stat-card"><span>Course</span><strong style="font-size:1.25rem"><?=e($student['course']??'Not set')?></strong></div><div class="stat-card"><span>Year of study</span><strong><?=e($student['year_of_study']??'—')?></strong></div><div class="stat-card"><span>Event registrations</span><strong><?=count($registrations)?></strong></div></div><?php if(!empty($dbError)): ?><div class="notice error">Could not load the database profile. Check the MySQL configuration.</div><?php endif; ?><div class="panel"><h2>My profile</h2><?php if($student): ?><div class="table-wrap"><table><tbody><tr><th>Name</th><td><?=e($student['full_name'])?></td></tr><tr><th>Email</th><td><?=e($student['email'])?></td></tr><tr><th>Mobile</th><td><?=e($student['mobile'])?></td></tr><tr><th>Course</th><td><?=e($student['course'])?></td></tr><tr><th>Year</th><td><?=e($student['year_of_study'])?></td></tr><tr><th>Gender</th><td><?=e($student['gender'])?></td></tr></tbody></table></div><?php else: ?><p class="muted">No student profile found. Contact the administrator.</p><?php endif; ?></div><div class="panel mt-24"><h2>My event registrations</h2><?php if($registrations): ?><div class="table-wrap"><table><thead><tr><th>Event</th><th>Date</th><th>Category</th><th>Registered</th></tr></thead><tbody><?php foreach($registrations as $row): ?><tr><td><?=e($row['title'])?></td><td><?=e($row['event_date'])?></td><td><?=e($row['category'])?></td><td><?=e($row['registered_at'])?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="muted">You haven't registered for an event yet. Visit the Events page to find one.</p><?php endif; ?></div></div></section>
<?php require __DIR__ . '/../includes/footer.php'; ?>
